<?php if (!defined('ABSPATH')) exit; $branding=rl_site(); ?>
<footer class="site-footer wrap"><div><a class="brand" href="<?php echo esc_url(rl_concert_home_url()); ?>"><?php if ($branding['logo_id']) echo wp_get_attachment_image($branding['logo_id'],'medium',false,['class'=>'brand-logo']); echo esc_html($branding['brand']); ?><span><?php echo esc_html($branding['subtitle']); ?></span></a><p><?php echo esc_html($branding['footer_text']); ?></p></div>
